"""Build the on-screen clocks, the end card and the tail-fin logo in light_speed.blend.

Run headless from the project root, after animate_speed.py (saves the .blend
in place):

    blender -b light_speed.blend --python scripts/build_hud.py

* Clocks: a readout in the top-left corner of the frame, text generated by
  Geometry Nodes (Format String -> String to Curves) from the baked
  F15["rapidity"], F15["distance_km"] and F15["earth_time_s"], so it updates
  every frame with no Python at render time. The pilot's clock is the
  animation clock; Earth's clock runs gamma times faster (35 minutes for the
  pilot's 25 seconds), which is the one contrast that explains the piece.
* End card: after the plane comes to rest at Jupiter, the trip's numbers fade
  in at the bottom and the RenderJuice wordmark in the top right corner.
* Tail-fin logo: the RenderJuice can on the outside of both tail fins, mixed
  into the fin paint, mirrored so it reads correctly from either side.

The text and logos sit on planes parented to the camera, one meter in front
of it, inside the frame computed from the camera's lens and shift. Safe to
re-run: everything is rebuilt.
"""

import math
import os
import sys

import bpy

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from animate_speed import ARRIVE_S, FPS, IGNITION_S, timeline  # noqa: E402
from build_sky_shader import AIRFRAME, RIG, Builder, Interface, new_group  # noqa: E402

FONT = os.path.join(os.path.dirname(bpy.app.binary_path), "..", "Resources",
                    f"{bpy.app.version[0]}.{bpy.app.version[1]}", "datafiles", "fonts", "DejaVuSansMono.woff2")
ICON = "//assets/RenderJuice-Logo-Pack/RenderJuice-Logo-Transparent-1024.png"
WORDMARK = "//assets/RenderJuice-Logo-Pack/RenderJuice-Local-Wordmarks/horizontal-large/renderjuice-lockup-white-transparent.png"

DEPTH = 1.0  # meters in front of the camera
MARGIN = 0.035  # of the frame width
READOUT_SIZE = 0.022  # text height, of the frame width
CARD_SIZE = 0.03
CARD_FADE_S = 0.6
TEXT_STRENGTH = 0.9
# Tail-fin logo: center (y, z) on the fin's outer face and size, in meters;
# above the fin's "BT" unit code (which is printed over the base color).
FIN_LOGO_CENTER = (7.75, 5.0)
FIN_LOGO_SIZE = 0.9


def frame_box(scene):
    """Camera-space (left, right, bottom, top) of the frame at DEPTH."""
    cam = scene.camera.data
    half_w = DEPTH * cam.sensor_width / (2.0 * cam.lens)
    half_h = half_w * scene.render.resolution_y / scene.render.resolution_x
    shift_x, shift_y = 2.0 * half_w * cam.shift_x, 2.0 * half_w * cam.shift_y
    return -half_w + shift_x, half_w + shift_x, -half_h + shift_y, half_h + shift_y


def add_driver(socket, expression, variables=()):
    socket.driver_remove("default_value")
    driver = socket.driver_add("default_value").driver
    driver.type = "SCRIPTED"
    for name, target, data_path in variables:
        var = driver.variables.new()
        var.name = name
        var.targets[0].id = target
        var.targets[0].data_path = data_path
    driver.expression = expression
    assert driver.is_simple_expression, expression


def fade_expression(start_frame):
    return f"min(max((frame - {start_frame}) / {CARD_FADE_S * FPS}, 0), 1)"


def overlay_material(name, image=None, fade_from=None):
    """Unlit, see-through overlay: white text, or an image with its alpha; optionally fading in."""
    mat = bpy.data.materials.get(name) or bpy.data.materials.new(name)
    mat.use_nodes = True
    mat.surface_render_method = "BLENDED"
    tree = mat.node_tree
    tree.nodes.clear()
    b = Builder(tree)
    emit = b.node("ShaderNodeEmission", 0, 100)
    emit.inputs["Strength"].default_value = TEXT_STRENGTH
    alpha = None
    if image is not None:
        tex = b.node("ShaderNodeTexImage", -400, 100, image=bpy.data.images.load(image, check_existing=True), extension="CLIP")
        b.link(tex.outputs["Color"], emit.inputs["Color"])
        alpha = tex.outputs["Alpha"]
    opacity = b.node("ShaderNodeValue", -400, -150, name="Opacity", label="Opacity")
    opacity.outputs[0].default_value = 1.0
    if fade_from is not None:
        add_driver(opacity.outputs[0], fade_expression(fade_from))
    factor = opacity.outputs[0] if alpha is None else b.math("MULTIPLY", alpha, opacity.outputs[0], x=-200, y=-100)
    mix = b.node("ShaderNodeMixShader", 200, 0)
    b.link(factor, mix.inputs["Fac"])
    b.link(b.node("ShaderNodeBsdfTransparent", 0, -100).outputs["BSDF"], mix.inputs[1])
    b.link(emit.outputs["Emission"], mix.inputs[2])
    b.link(mix.outputs["Shader"], b.node("ShaderNodeOutputMaterial", 400, 0).inputs["Surface"])
    return mat


def format_node(b, fmt, items, x, y):
    """Format String node; items are (name, socket_type, source socket or value)."""
    node = b.node("FunctionNodeFormatString", x, y)
    node.inputs["Format"].default_value = fmt
    for name, kind, source in items:
        node.format_items.new(kind, name)
        if isinstance(source, bpy.types.NodeSocket):
            b.link(source, node.inputs[name])
        else:
            node.inputs[name].default_value = source
    return node.outputs["String"]


def text_geometry(b, string, size, align, material, x, y):
    font = bpy.data.fonts.load(FONT, check_existing=True)
    curves = b.node("GeometryNodeStringToCurves", x, y, font=font, align_x=align, align_y="TOP")
    b.link(string, curves.inputs["String"])
    curves.inputs["Size"].default_value = size
    realize = b.node("GeometryNodeRealizeInstances", x + 200, y)
    b.link(curves.outputs["Curve Instances"], realize.inputs["Geometry"])
    fill = b.node("GeometryNodeFillCurve", x + 400, y, mode="NGONS")
    b.link(realize.outputs["Geometry"], fill.inputs["Curve"])
    set_mat = b.node("GeometryNodeSetMaterial", x + 600, y)
    set_mat.inputs["Material"].default_value = material
    b.link(fill.outputs["Mesh"], set_mat.inputs["Geometry"])
    return set_mat.outputs["Geometry"]


def build_readout_group(size, material):
    group = new_group("ClockReadout", "GeometryNodeTree")
    face = Interface(group)
    face.new_socket("Geometry", in_out="INPUT", socket_type="NodeSocketGeometry")
    face.new_socket("Geometry", in_out="OUTPUT", socket_type="NodeSocketGeometry")
    for name in ("Rapidity", "Distance", "Earth Time"):
        face.new_socket(name, in_out="INPUT", socket_type="NodeSocketFloat")
    face.done()

    b = Builder(group)
    inp = b.node("NodeGroupInput", -1600, 0)
    out = b.node("NodeGroupOutput", 1200, 0)
    phi = inp.outputs["Rapidity"]

    def clock(seconds, x, y):
        minutes = b.math("FLOOR", b.math("DIVIDE", seconds, 60.0, x=x, y=y), x=x + 150, y=y)
        rest = b.math("SUBTRACT", seconds, b.math("MULTIPLY", minutes, 60.0, x=x + 300, y=y - 100), x=x + 450, y=y)
        return minutes, rest

    pilot_m, pilot_s = clock(b.node("GeometryNodeInputSceneTime", -1600, 400).outputs["Seconds"], -1400, 400)
    earth_m, earth_s = clock(inp.outputs["Earth Time"], -1400, 200)
    # beta = tanh(phi), gamma = cosh(phi)
    beta = b.math("TANH", phi, x=-1200, y=0)
    gamma = b.math("COSH", phi, x=-1200, y=-150)
    # Distance in km below a million, then in millions of km.
    km = inp.outputs["Distance"]
    small = format_node(b, "{d:.0f} km", [("d", "FLOAT", km)], -1000, -300)
    large = format_node(b, "{d:.1f} million km", [("d", "FLOAT", b.math("DIVIDE", km, 1e6, x=-1200, y=-450))], -1000, -450)
    pick = b.node("GeometryNodeSwitch", -800, -350, input_type="STRING")
    b.link(b.math("GREATER_THAN", km, 1e6, x=-1000, y=-600), pick.inputs["Switch"])
    b.link(small, pick.inputs["False"])
    b.link(large, pick.inputs["True"])

    text = format_node(b, "\n".join((
        "PILOT CLOCK  {pm:02.0f}:{ps:04.1f}",
        "EARTH CLOCK  {em:02.0f}:{es:04.1f}",
        "SPEED        {beta:.7f} c",
        "GAMMA        {gamma:.1f}",
        "DISTANCE     {dist}",
    )), [("pm", "FLOAT", pilot_m), ("ps", "FLOAT", pilot_s), ("em", "FLOAT", earth_m), ("es", "FLOAT", earth_s),
         ("beta", "FLOAT", beta), ("gamma", "FLOAT", gamma), ("dist", "STRING", pick.outputs["Output"])], -400, 0)
    b.link(text_geometry(b, text, size, "LEFT", material, 0, 0), out.inputs["Geometry"])
    return group


def build_card_group(text, size, material):
    group = new_group("EndCardText", "GeometryNodeTree")
    face = Interface(group)
    face.new_socket("Geometry", in_out="INPUT", socket_type="NodeSocketGeometry")
    face.new_socket("Geometry", in_out="OUTPUT", socket_type="NodeSocketGeometry")
    face.done()
    b = Builder(group)
    out = b.node("NodeGroupOutput", 1000, 0)
    string = format_node(b, text, [], -400, 0)
    b.link(text_geometry(b, string, size, "CENTER", material, 0, 0), out.inputs["Geometry"])
    return group


def overlay_object(name, camera, location, mesh=None):
    mesh = mesh or bpy.data.meshes.get(name) or bpy.data.meshes.new(name)
    obj = bpy.data.objects.get(name) or bpy.data.objects.new(name, mesh)
    obj.data = mesh
    coll = bpy.data.collections.get("Overlay") or bpy.data.collections.new("Overlay")
    if coll.name not in bpy.context.scene.collection.children:
        bpy.context.scene.collection.children.link(coll)
    for c in list(obj.users_collection):
        c.objects.unlink(obj)
    coll.objects.link(obj)
    obj.parent = camera
    obj.matrix_parent_inverse.identity()
    obj.location = location
    obj.rotation_euler = (0.0, 0.0, 0.0)
    obj.visible_shadow = False
    obj.modifiers.clear()
    return obj


def image_plane(name, image, width):
    """Quad of the given width with the image's aspect ratio, centered on the origin."""
    img = bpy.data.images.load(image, check_existing=True)
    height = width * img.size[1] / img.size[0]
    mesh = bpy.data.meshes.get(name) or bpy.data.meshes.new(name)
    mesh.clear_geometry()
    w, h = width / 2, height / 2
    mesh.from_pydata([(-w, -h, 0), (w, -h, 0), (w, h, 0), (-w, h, 0)], [], [(0, 1, 2, 3)])
    uv = mesh.uv_layers.new(name="UVMap") if not mesh.uv_layers else mesh.uv_layers[0]
    for loop, coord in zip(uv.data, ((0, 0), (1, 0), (1, 1), (0, 1))):
        loop.uv = coord
    return mesh, height


def arrival_numbers(rig, scene, frame):
    curves = {fc.data_path: fc for fc in rig.animation_data.action.fcurves}
    return curves['["distance_km"]'].evaluate(frame), curves['["earth_time_s"]'].evaluate(frame)


def build_fin_logo(airframe):
    """Mix the RenderJuice can into the fin paint's base color, on both fins' outer faces."""
    group = new_group("FinLogo")
    face = Interface(group)
    face.new_socket("Color", in_out="INPUT", socket_type="NodeSocketColor")
    face.new_socket("Color", in_out="OUTPUT", socket_type="NodeSocketColor")
    face.done()
    b = Builder(group)
    inp = b.node("NodeGroupInput", -1400, 0)
    out = b.node("NodeGroupOutput", 600, 0)
    coord = b.node("ShaderNodeTexCoord", -1400, 300, object=airframe)
    pos = b.node("ShaderNodeSeparateXYZ", -1200, 300)
    b.link(coord.outputs["Object"], pos.inputs["Vector"])
    normal = b.node("ShaderNodeSeparateXYZ", -1200, 0)
    b.link(b.node("ShaderNodeNewGeometry", -1400, 0).outputs["Normal"], normal.inputs["Vector"])
    # Which side we are on, and whether this face looks outward.
    side = b.math("SIGN", pos.outputs["X"], x=-1000, y=400)
    outward = b.math("GREATER_THAN", b.math("MULTIPLY", normal.outputs["X"], side, x=-1000, y=100), 0.5, x=-850, y=100)
    # Seen from outside, the tail is to the right on the +X fin and to the left on the -X fin.
    y0, z0 = FIN_LOGO_CENTER
    u = b.math("ADD", b.math("MULTIPLY", b.math("DIVIDE", b.math("SUBTRACT", pos.outputs["Y"], y0, x=-1000, y=300), FIN_LOGO_SIZE, x=-850, y=300), side, x=-700, y=300), 0.5, x=-550, y=300)
    v = b.math("ADD", b.math("DIVIDE", b.math("SUBTRACT", pos.outputs["Z"], z0, x=-1000, y=200), FIN_LOGO_SIZE, x=-850, y=200), 0.5, x=-700, y=200)
    uv = b.node("ShaderNodeCombineXYZ", -400, 250)
    b.link(u, uv.inputs["X"])
    b.link(v, uv.inputs["Y"])
    tex = b.node("ShaderNodeTexImage", -200, 250, image=bpy.data.images.load(ICON, check_existing=True), extension="CLIP")
    b.link(uv.outputs["Vector"], tex.inputs["Vector"])
    mix = b.node("ShaderNodeMix", 300, 0, data_type="RGBA")
    b.link(b.math("MULTIPLY", tex.outputs["Alpha"], outward, x=100, y=100), mix.inputs["Factor"])
    b.link(inp.outputs["Color"], mix.inputs["A"])
    b.link(tex.outputs["Color"], mix.inputs["B"])
    b.link(mix.outputs["Result"], out.inputs["Color"])

    mat = bpy.data.materials["f15_fin_paint_side"]
    tree = mat.node_tree
    bsdf = next(n for n in tree.nodes if n.bl_idname == "ShaderNodeBsdfPrincipled")
    logo = tree.nodes.get("FinLogo")
    if logo is None:
        logo = tree.nodes.new("ShaderNodeGroup")
        logo.name = logo.label = "FinLogo"
        logo.location = (bsdf.location.x - 250, bsdf.location.y + 200)
    logo.node_tree = group
    feed = logo.inputs[0].links or [l for l in bsdf.inputs["Base Color"].links if l.from_node != logo]
    if feed:
        tree.links.new(feed[0].from_socket, logo.inputs[0])
    else:
        logo.inputs[0].default_value = bsdf.inputs["Base Color"].default_value
    tree.links.new(logo.outputs[0], bsdf.inputs["Base Color"])


def build():
    scene = bpy.context.scene
    rig = bpy.data.objects[RIG]
    camera = scene.camera
    left, right, bottom, top = frame_box(scene)
    width = right - left
    margin = MARGIN * width

    # Clocks, top left.
    text_mat = overlay_material("OverlayText")
    readout = overlay_object("ClockReadout", camera, (left + margin, top - margin, -DEPTH))
    mod = readout.modifiers.new("ClockReadout", "NODES")
    mod.node_group = build_readout_group(READOUT_SIZE * width, text_mat)
    ids = {s.name: s.identifier for s in mod.node_group.interface.items_tree if s.in_out == "INPUT"}
    for socket, prop in (("Rapidity", "rapidity"), ("Distance", "distance_km"), ("Earth Time", "earth_time_s")):
        path = f'modifiers["ClockReadout"]["{ids[socket]}"]'
        readout.driver_remove(path)
        driver = readout.driver_add(path).driver
        driver.type = "AVERAGE"
        var = driver.variables.new()
        var.targets[0].id = rig
        var.targets[0].data_path = f'["{prop}"]'

    # End card, bottom center, once the plane is at rest.
    _, _, brake_end, _ = timeline()
    rest_s = brake_end + IGNITION_S
    card_frame = 1 + round((rest_s + 0.3) * FPS)
    km, earth_s = arrival_numbers(rig, scene, card_frame)
    card_text = (f"{km / 1e6:.0f} million km to Jupiter\n"
                 f"{rest_s:.0f} seconds for the pilot, {earth_s / 60:.0f} minutes on Earth")
    card_mat = overlay_material("EndCardText", fade_from=card_frame)
    card = overlay_object("EndCardText", camera, (0.5 * (left + right), bottom + 0.2 * (top - bottom), -DEPTH))
    card.modifiers.new("EndCardText", "NODES").node_group = build_card_group(card_text, CARD_SIZE * width, card_mat)

    # RenderJuice wordmark, top right (across from the clocks), fading in a little after the text.
    mark_mesh, mark_h = image_plane("RenderJuiceWordmark", WORDMARK, 0.18 * width)
    mark_mesh.materials.clear()
    mark_mesh.materials.append(overlay_material("RenderJuiceWordmark", WORDMARK, fade_from=card_frame + round(0.5 * FPS)))
    overlay_object("RenderJuiceWordmark", camera, (right - margin - 0.09 * width, top - margin - mark_h / 2, -DEPTH), mark_mesh)

    build_fin_logo(bpy.data.objects[AIRFRAME])
    print(f"End card at frame {card_frame}: {card_text!r}")


if __name__ == "__main__":
    build()
    bpy.ops.wm.save_mainfile()
